import{_ as a,o as i,c as e,aO as n}from"./chunks/framework.vjUPZZJn.js";const b=JSON.parse('{"title":"eXtremeDB ARM 构建失败排查","description":"","frontmatter":{"date":"2026-10-08T16:40:00.000Z","title":"eXtremeDB ARM 构建失败排查","source":[["1-知识/问题记录/eXtremeDB ARM 构建失败排查"]],"tags":["数据库","问题排查","eXtremeDB","glibc"],"categories":["问题排查"],"permalink":"/pages/8278e3"},"headers":[],"relativePath":"问题排查/eXtremeDB ARM 构建失败排查.md","filePath":"问题排查/eXtremeDB ARM 构建失败排查.md","lastUpdated":1791444359000}'),l={name:"问题排查/eXtremeDB ARM 构建失败排查.md"};function t(p,s,r,h,c,d){return i(),e("div",null,[...s[0]||(s[0]=[n(`<h1 id="extremedb-arm-构建失败排查" tabindex="-1">eXtremeDB ARM 构建失败排查 <a class="header-anchor" href="#extremedb-arm-构建失败排查" aria-label="Permalink to &quot;eXtremeDB ARM 构建失败排查&quot;">​</a></h1> <p>在 ARM64 目标机上解压 eXtremeDB 发行包后直接 <code>make</code> 会失败，报错指向示例工程的 DDL 产物。本文记录一次完整的定位过程：从报错确认发行包自带的工具链架构不匹配，到中途尝试「升级系统 glibc」走入的弯路，最后回到在 x86_64 主机上交叉编译的正解。核心教训有两条：发行包里的 host 工具和目标机架构要分清；系统的 libc 软链接不能动。</p> <h2 id="现象" tabindex="-1">现象 <a class="header-anchor" href="#现象" aria-label="Permalink to &quot;现象&quot;">​</a></h2> <p>解压 <code>extremedb_8.3_fusion_linux_arm64_eval.tar.gz</code>（eXtremeDB 8.3 评估版，ARM64 目标平台）后，在根目录运行 <code>make</code> 报错：</p> <div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> ***</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [/home/user/eXtremeDB/include/rules.makefile:717: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/home/user/eXtremeDB/samples/native/core/00-ddl/obj-00-ddl-Linux-arm64-exec-offs-ndbg/sampleddl.h]</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Error</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>目标机环境：ARM64 开发板，Ubuntu 20.04，gcc 9.4.0，glibc 2.31。</p> <h2 id="定位过程" tabindex="-1">定位过程 <a class="header-anchor" href="#定位过程" aria-label="Permalink to &quot;定位过程&quot;">​</a></h2> <h3 id="第一步-报错源头是-ddl-编译器" tabindex="-1">第一步：报错源头是 DDL 编译器 <a class="header-anchor" href="#第一步-报错源头是-ddl-编译器" aria-label="Permalink to &quot;第一步：报错源头是 DDL 编译器&quot;">​</a></h3> <p>按文档先单独跑 DDL 编译器验证：</p> <div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ../../host/bin/mcocomp mydb.mco</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ../../host/bin/mcocomp:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cannot</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> execute</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> binary</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> file:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> format</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> error</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><code>mcocomp</code> 是 eXtremeDB 的 DDL 模式编译器（McObject 官方文档明确此角色）：把 <code>.mco</code> 模式定义文件编译成数据库字典和接口代码。<code>Exec format error</code> 说明这个二进制的架构与当前机器不符——<strong>评估包虽然面向 arm64 目标平台，附带的 host 工具却是 x86_64 版本的</strong>，无法在 ARM 主机上运行。</p> <h3 id="第二步-换-arm-版工具-报错变为-glibc-版本不满足" tabindex="-1">第二步：换 ARM 版工具，报错变为 glibc 版本不满足 <a class="header-anchor" href="#第二步-换-arm-版工具-报错变为-glibc-版本不满足" aria-label="Permalink to &quot;第二步：换 ARM 版工具，报错变为 glibc 版本不满足&quot;">​</a></h3> <p>从厂商获取 ARM 平台的 <code>mcocomp</code> 替换后再跑，报错变成：</p> <div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">./</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">./host/bin/mcocomp:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /lib/aarch64-linux-gnu/libc.so.6:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> version</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> \`</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">GLIBC_2.34&#39; not found (required by ../../host/bin/mcocomp)</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><code>GLIBC_x.y not found</code> 的含义是确定的：这个二进制要求 glibc 2.34 引入的符号版本，而 Ubuntu 20.04 的系统 glibc 是 2.31。确认一下系统提供的版本上限：</p> <div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># strings /lib/aarch64-linux-gnu/libc.so.6 | grep GLIBC_</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">GLIBC_2.17</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">GLIBC_2.18</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">...</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">GLIBC_2.30</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>确实没有 2.34。此时正确的方向其实已经清楚了（后面会说），但当时先走了另一条路。</p> <h3 id="第三步-弯路——替换系统-glibc" tabindex="-1">第三步：弯路——替换系统 glibc <a class="header-anchor" href="#第三步-弯路——替换系统-glibc" aria-label="Permalink to &quot;第三步：弯路——替换系统 glibc&quot;">​</a></h3> <p>尝试在用户目录源码编译 glibc 2.34（<code>--prefix=$HOME/glibc/glibc-2.34-install</code>，configure 阶段需补装 gawk、bison 两个依赖），编译安装本身成功。接着把系统 libc 的软链接指了过去：</p> <div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># cp -d /lib/aarch64-linux-gnu/libc.so.6 /lib/aarch64-linux-gnu/libc.so.6.bak</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ln -sf $HOME/glibc/glibc-2.34-install/lib/libc.so.6 /lib/aarch64-linux-gnu/libc.so.6</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ll /lib/aarch64-linux-gnu/libc.so.6.bak</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Segmentation</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fault</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>替换之后，<code>ll</code> 这样的基础命令立即段错误，只能靠备份恢复软链接。原因不难理解：系统里几乎所有动态链接程序都依赖 <code>/lib</code> 下的 libc，用手工商定时、与前缀不配套的 glibc 顶替系统版本，等于让所有进程依赖一个未经验证的 libc 实现。<strong>用户态前缀安装的高版本 glibc 可以保留，但只能按进程配合指定动态链接器与库搜索路径来用，不能通过修改系统软链接全局生效。</strong></p> <h2 id="正确解法-回主机交叉编译" tabindex="-1">正确解法：回主机交叉编译 <a class="header-anchor" href="#正确解法-回主机交叉编译" aria-label="Permalink to &quot;正确解法：回主机交叉编译&quot;">​</a></h2> <p>回头看清问题本质：eXtremeDB 的构建模型本来就是「host 编译、target 运行」——DDL 编译器和整套构建本该在 x86_64 开发主机上执行，产物再部署到 ARM 目标机。厂商给出的标准流程是在 x86_64 Linux 主机上：</p> <div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PATH</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/opt/toolchains/gcc-11.3/arm-gnu-toolchain-11.3.rel1-x86_64-aarch64-none-linux-gnu/bin:$PATH</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> TARGET_PLATFORM=aarch64-none-linux-gnu</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> all</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>即配置好目标平台的交叉工具链后指定 <code>TARGET_PLATFORM</code> 一次构建，不同目标环境换对应 toolchain。这也是嵌入式开发的通用做法：目标机上凑工具链，不如在主机上交叉编译。</p> <h2 id="要点" tabindex="-1">要点 <a class="header-anchor" href="#要点" aria-label="Permalink to &quot;要点&quot;">​</a></h2> <ul><li><code>Exec format error</code> 先查二进制架构（<code>file</code> 命令），发行包「面向某目标平台」不等于其附带的 host 工具能在该平台运行；</li> <li><code>GLIBC_x.y not found</code> 说明二进制要求的 glibc 高于系统版本，处理方向是换匹配的二进制或交叉编译，不是升系统 glibc；</li> <li>手工编译的 glibc 只能配合显式指定动态链接器按进程使用，替换 <code>/lib</code> 下的 libc 软链接会让全系统命令立刻段错误；</li> <li>数据库这类带代码生成器的 SDK，构建模型通常是 host/target 分离的，目标机直接 <code>make</code> 前先确认文档里对构建主机的假设。</li></ul>`,47)])])}const k=a(l,[["render",t]]);export{b as __pageData,k as default};
